int remocoes(vector<long long> a,long long k) {
    if(a.empty()) return 0;
    sort(a.begin(),a.end());
    int atual=1,melhor=1;
    for(int i=1;i<(int)a.size();++i){
        atual=(a[i]-a[i-1]<=k ? atual+1 : 1);
        melhor=max(melhor,atual);
    }
    return (int)a.size()-melhor;
}
